BEGIN;
CREATE TABLE IF NOT EXISTS editorial_users(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,email text NOT NULL UNIQUE,password_hash text NOT NULL,display_name text NOT NULL,role text NOT NULL CHECK(role IN ('superadmin','editor','moderator','advertiser')),enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ingestion_sources(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,source_name text NOT NULL,feed_url text NOT NULL UNIQUE,protocol text NOT NULL DEFAULT 'rss' CHECK(protocol IN ('rss','atom','gtfs','gtfs-rt','api')),enabled boolean NOT NULL DEFAULT false,approved boolean NOT NULL DEFAULT false,last_checked_at timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now(),CHECK(feed_url LIKE 'https://%'));
CREATE TABLE IF NOT EXISTS ingestion_candidates(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,source_id bigint NOT NULL REFERENCES ingestion_sources(id),title varchar(300) NOT NULL,summary varchar(1500) NOT NULL DEFAULT '',source_url varchar(2000) NOT NULL UNIQUE,published_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','rejected','approved')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS content_items(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,category varchar(60) NOT NULL,title varchar(300) NOT NULL,summary varchar(2500) NOT NULL DEFAULT '',neighborhood varchar(120),source_name varchar(240) NOT NULL,source_url varchar(2000) NOT NULL UNIQUE,author_name varchar(240),image_url varchar(2000),image_credit varchar(300),image_license varchar(120),address varchar(500),event_at timestamptz,end_at timestamptz,ticket_price numeric(12,2) CHECK(ticket_price>=0),published_at timestamptz NOT NULL DEFAULT now(),last_verified_at timestamptz NOT NULL DEFAULT now(),verification_status varchar(30) NOT NULL DEFAULT 'pending' CHECK(verification_status IN ('pending','verified','outdated')),status varchar(30) NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','review','published','archived')),reviewed_by bigint REFERENCES editorial_users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_content_public ON content_items(status,category,published_at DESC);
CREATE TABLE IF NOT EXISTS community_submissions(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,display_name varchar(100) NOT NULL,message varchar(2500) NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),created_at timestamptz NOT NULL DEFAULT now(),reviewed_by bigint REFERENCES editorial_users(id));
CREATE TABLE IF NOT EXISTS public_transport_lines(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,agency text NOT NULL,line_code varchar(50) NOT NULL,description text,source_url text,last_verified_at timestamptz,UNIQUE(agency,line_code));
CREATE TABLE IF NOT EXISTS transport_stops(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,agency text NOT NULL,stop_code text NOT NULL,name text NOT NULL,latitude numeric(10,7),longitude numeric(10,7),UNIQUE(agency,stop_code));
CREATE TABLE IF NOT EXISTS transport_alerts(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,title text NOT NULL,description text NOT NULL,source_url text NOT NULL,valid_from timestamptz NOT NULL,valid_to timestamptz,verified boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS advertiser_campaigns(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,advertiser_name text NOT NULL,destination_url text NOT NULL,image_url text,label text NOT NULL DEFAULT 'Publicidade',active boolean NOT NULL DEFAULT false,valid_from timestamptz,valid_to timestamptz);
CREATE TABLE IF NOT EXISTS ai_review_jobs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,provider text NOT NULL,candidate_id bigint REFERENCES ingestion_candidates(id),status text NOT NULL DEFAULT 'pending',output_text text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,actor_id bigint REFERENCES editorial_users(id),action text NOT NULL,entity_type text NOT NULL,entity_id bigint,details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
COMMIT;